gboolean bank_observation_dao_insert_analysis(BankObservationDao*d,const BankAnalysisRecord*r,GError**e){BankAnalysisRecord*v=bank_analysis_record_copy(r);if(!d||!v){fail(e,"Analyse bancaire invalide.");return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO bank_analyses VALUES(?,?,?,?,?,?,?,?);");gboolean ok=s&&bind(s,1,v->id)&&bind(s,2,v->investigation_id)&&bind(s,3,v->evidence_id)&&bind(s,4,v->evidence_sha256)&&bind(s,5,v->extraction_method)&&bind(s,6,v->source_kind)&&bind(s,7,v->created_at)&&bind(s,8,bank_origin_to_code(v->origin))&&done(s);database_statement_finalize(s);bank_analysis_record_free(v);if(!ok)fail(e,"Insertion de l’analyse bancaire impossible.");return ok;}
gboolean bank_observation_dao_insert(BankObservationDao*d,const BankObservationRecord*r,GError**e){BankObservationRecord*v=bank_observation_record_copy(r);if(!d||!v){fail(e,"Observation bancaire invalide.");return FALSE;}if(!database_transaction_begin(d->d)){bank_observation_record_free(v);fail(e,"Transaction impossible.");return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO bank_observations(id,analysis_id,investigation_id,evidence_id,evidence_sha256,occurrence_type,raw_value,start_offset,end_offset,extraction_rule,technical_validation,page_or_image,ocr_run_id,region_x,region_y,region_width,region_height,source_context,origin,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);");gboolean ok=s&&bind(s,1,v->id)&&bind(s,2,v->analysis_id)&&bind(s,3,v->investigation_id)&&bind(s,4,v->evidence_id)&&bind(s,5,v->evidence_sha256)&&bind(s,6,v->occurrence_type)&&bind(s,7,v->raw_value)&&database_statement_bind_int64(s,8,(int64_t)v->start_offset)&&database_statement_bind_int64(s,9,(int64_t)v->end_offset)&&bind(s,10,v->extraction_rule)&&bind(s,11,bank_validation_state_to_code(v->validation))&&bind(s,12,v->page_or_image)&&bind(s,13,v->ocr_run_id)&&bind(s,14,v->region_x)&&bind(s,15,v->region_y)&&bind(s,16,v->region_width)&&bind(s,17,v->region_height)&&bind(s,18,v->source_context)&&bind(s,19,bank_origin_to_code(v->origin))&&bind(s,20,v->created_at)&&done(s);database_statement_finalize(s);for(guint i=0;ok&&i<v->warnings->len;i++){s=database_statement_prepare(d->d,"INSERT INTO bank_observation_warnings VALUES(?,?,?);");ok=s&&bind(s,1,v->id)&&database_statement_bind_int64(s,2,i)&&bind(s,3,g_ptr_array_index(v->warnings,i))&&done(s);database_statement_finalize(s);}ok=ok&&database_transaction_commit(d->d);if(!ok&&database_transaction_is_active(d->d))database_transaction_rollback(d->d);bank_observation_record_free(v);if(!ok)fail(e,"Insertion de l’observation impossible.");return ok;}
static BankValidationState validation_from(const char*v){return g_strcmp0(v,"valid")==0?BANK_VALIDATION_VALID:g_strcmp0(v,"invalid")==0?BANK_VALIDATION_INVALID:g_strcmp0(v,"ambiguous")==0?BANK_VALIDATION_AMBIGUOUS:BANK_VALIDATION_UNVERIFIABLE;}
static BankOrigin origin_from(const char*v){return g_strcmp0(v,"human")==0?BANK_ORIGIN_HUMAN:g_strcmp0(v,"legacy")==0?BANK_ORIGIN_LEGACY:BANK_ORIGIN_AUTOMATIC;}
static BankObservationRecord *read_observation(DatabaseStatement*s){char*v[20]={0};int64_t a=0,b=0;gboolean ok=TRUE;for(int i=0;i<7;i++)ok&=database_statement_column_text(s,i,&v[i]);ok&=database_statement_column_int64(s,7,&a)&&database_statement_column_int64(s,8,&b);for(int i=9;i<20;i++)ok&=database_statement_column_text(s,i,&v[i]);BankObservationRecord x={.id=v[0],.analysis_id=v[1],.investigation_id=v[2],.evidence_id=v[3],.evidence_sha256=v[4],.occurrence_type=v[5],.raw_value=v[6],.start_offset=(gsize)a,.end_offset=(gsize)b,.extraction_rule=v[9],.validation=validation_from(v[10]),.page_or_image=v[11],.ocr_run_id=v[12],.region_x=v[13],.region_y=v[14],.region_width=v[15],.region_height=v[16],.source_context=v[17],.origin=origin_from(v[18]),.created_at=v[19]};BankObservationRecord*r=ok?bank_observation_record_copy(&x):NULL;for(int i=0;i<20;i++)g_free(v[i]);return r;}
static gboolean load_warnings(BankObservationDao*d,BankObservationRecord*r){DatabaseStatement*s=database_statement_prepare(d->d,"SELECT warning FROM bank_observation_warnings WHERE observation_id=? ORDER BY position;");if(!s||!bind(s,1,r->id)){database_statement_finalize(s);return FALSE;}for(;;){DatabaseStatementStepResult step=database_statement_step(s);if(step==DATABASE_STATEMENT_STEP_DONE)break;if(step!=DATABASE_STATEMENT_STEP_ROW){database_statement_finalize(s);return FALSE;}char*w=NULL;if(!database_statement_column_text(s,0,&w)){database_statement_finalize(s);return FALSE;}g_ptr_array_add(r->warnings,w);}database_statement_finalize(s);return TRUE;}
static GPtrArray *observation_query(BankObservationDao*d,const char*where,const char*id,GError**e){char*sql=g_strdup_printf("SELECT id,analysis_id,investigation_id,evidence_id,evidence_sha256,occurrence_type,raw_value,start_offset,end_offset,extraction_rule,technical_validation,page_or_image,ocr_run_id,region_x,region_y,region_width,region_height,source_context,origin,created_at FROM bank_observations WHERE %s ORDER BY created_at,id;",where);DatabaseStatement*s=database_statement_prepare(d?d->d:NULL,sql);g_free(sql);GPtrArray*a=g_ptr_array_new_with_free_func((GDestroyNotify)bank_observation_record_free);if(!s||!bind(s,1,id))goto bad;for(;;){DatabaseStatementStepResult step=database_statement_step(s);if(step==DATABASE_STATEMENT_STEP_DONE)break;if(step!=DATABASE_STATEMENT_STEP_ROW)goto bad;BankObservationRecord*r=read_observation(s);if(!r||!load_warnings(d,r)){bank_observation_record_free(r);goto bad;}g_ptr_array_add(a,r);}database_statement_finalize(s);return a;bad:database_statement_finalize(s);g_ptr_array_unref(a);fail(e,"Lecture des observations impossible.");return NULL;}
BankObservationRecord *bank_observation_dao_find(BankObservationDao*d,const char*id,GError**e){GPtrArray*a=observation_query(d,"id=?",id,e);if(!a)return NULL;BankObservationRecord*r=a->len?bank_observation_record_copy(g_ptr_array_index(a,0)):NULL;g_ptr_array_unref(a);return r;}
GPtrArray *bank_observation_dao_list_by_evidence(BankObservationDao*d,const char*id,GError**e){return observation_query(d,"evidence_id=?",id,e);}

gboolean bank_review_dao_insert_proposal(BankReviewDao*d,const BankProposalRecord*r,GError**e){BankProposalRecord*v=bank_proposal_record_copy(r);if(!d||!v||v->roles->len!=v->observation_ids->len){bank_proposal_record_free(v);fail(e,"Proposition bancaire invalide.");return FALSE;}if(!database_transaction_begin(d->d)){bank_proposal_record_free(v);return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO bank_proposals VALUES(?,?,?,?,?,?,?,?);");gboolean ok=s&&bind(s,1,v->id)&&bind(s,2,v->investigation_id)&&bind(s,3,v->evidence_id)&&database_statement_bind_int64(s,4,v->start_offset)&&database_statement_bind_int64(s,5,v->end_offset)&&database_statement_bind_int64(s,6,v->ambiguous)&&bind(s,7,bank_origin_to_code(v->origin))&&bind(s,8,v->created_at)&&done(s);database_statement_finalize(s);for(guint i=0;ok&&i<v->observation_ids->len;i++){s=database_statement_prepare(d->d,"INSERT INTO bank_proposal_observations VALUES(?,?,?,?);");ok=s&&bind(s,1,v->id)&&bind(s,2,g_ptr_array_index(v->observation_ids,i))&&database_statement_bind_int64(s,3,i)&&bind(s,4,g_ptr_array_index(v->roles,i))&&done(s);database_statement_finalize(s);}for(guint i=0;ok&&i<v->reasons->len;i++){s=database_statement_prepare(d->d,"INSERT INTO bank_proposal_reasons VALUES(?,?,?);");ok=s&&bind(s,1,v->id)&&database_statement_bind_int64(s,2,i)&&bind(s,3,g_ptr_array_index(v->reasons,i))&&done(s);database_statement_finalize(s);}ok=ok&&database_transaction_commit(d->d);if(!ok&&database_transaction_is_active(d->d))database_transaction_rollback(d->d);bank_proposal_record_free(v);if(!ok)fail(e,"Insertion de la proposition impossible.");return ok;}
gboolean bank_review_dao_insert_revision(BankReviewDao*d,const BankRevisionRecord*r,GError**e){BankRevisionRecord*v=bank_revision_record_copy(r);if(!d||!v){fail(e,"Révision bancaire invalide.");return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO bank_observation_revisions VALUES(?,?,?,?,?,?,?,?,?);");gboolean ok=s&&bind(s,1,v->id)&&bind(s,2,v->observation_id)&&bind(s,3,v->corrected_value)&&bind(s,4,v->normalized_value)&&bind(s,5,bank_validation_state_to_code(v->validation))&&bind(s,6,v->factual_notes)&&bind(s,7,v->author)&&bind(s,8,"human")&&bind(s,9,v->created_at)&&done(s);database_statement_finalize(s);bank_revision_record_free(v);if(!ok)fail(e,"Insertion de la révision impossible.");return ok;}
gboolean bank_review_dao_insert_decision(BankReviewDao*d,const BankDecisionRecord*r,GError**e){BankDecisionRecord*v=bank_decision_record_copy(r);if(!d||!v){fail(e,"Décision bancaire invalide.");return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO bank_decisions VALUES(?,?,?,?,?,?,?,?,?,?,?);");gboolean ok=s&&bind(s,1,v->id)&&bind(s,2,v->observation_id)&&bind(s,3,v->proposal_id)&&bind(s,4,v->revision_id)&&bind(s,5,bank_human_decision_to_code(v->decision))&&bind(s,6,"human")&&bind(s,7,v->created_at)&&database_statement_bind_int64(s,8,v->create_account)&&database_statement_bind_int64(s,9,v->reuse_account)&&database_statement_bind_int64(s,10,v->create_holder)&&database_statement_bind_int64(s,11,v->create_transaction)&&done(s);database_statement_finalize(s);bank_decision_record_free(v);if(!ok)fail(e,"Insertion de la décision impossible.");return ok;}
static BankRevisionRecord *read_revision(DatabaseStatement*s){char*v[9]={0};gboolean ok=TRUE;for(int i=0;i<9;i++)ok&=database_statement_column_text(s,i,&v[i]);BankRevisionRecord x={.id=v[0],.observation_id=v[1],.corrected_value=v[2],.normalized_value=v[3],.validation=validation_from(v[4]),.factual_notes=v[5],.author=v[6],.created_at=v[8]};BankRevisionRecord*r=ok?bank_revision_record_copy(&x):NULL;for(int i=0;i<9;i++)g_free(v[i]);return r;}
static GPtrArray *revision_query(BankReviewDao*d,const char*where,const char*id,GError**e){char*sql=g_strdup_printf("SELECT * FROM bank_observation_revisions WHERE %s ORDER BY created_at,id;",where);DatabaseStatement*s=database_statement_prepare(d?d->d:NULL,sql);g_free(sql);GPtrArray*a=g_ptr_array_new_with_free_func((GDestroyNotify)bank_revision_record_free);if(!s||!bind(s,1,id))goto bad;for(;;){DatabaseStatementStepResult step=database_statement_step(s);if(step==DATABASE_STATEMENT_STEP_DONE)break;if(step!=DATABASE_STATEMENT_STEP_ROW)goto bad;BankRevisionRecord*r=read_revision(s);if(!r)goto bad;g_ptr_array_add(a,r);}database_statement_finalize(s);return a;bad:database_statement_finalize(s);g_ptr_array_unref(a);fail(e,"Lecture des révisions impossible.");return NULL;}
GPtrArray *bank_review_dao_list_revisions(BankReviewDao*d,const char*id,GError**e){return revision_query(d,"observation_id=?",id,e);}
BankRevisionRecord *bank_review_dao_find_revision(BankReviewDao*d,const char*id,GError**e){GPtrArray*a=revision_query(d,"id=?",id,e);if(!a)return NULL;BankRevisionRecord*r=a->len?bank_revision_record_copy(g_ptr_array_index(a,0)):NULL;g_ptr_array_unref(a);return r;}
static BankHumanDecision decision_from(const char*v){return g_strcmp0(v,"confirmed")==0?BANK_DECISION_CONFIRMED:g_strcmp0(v,"rejected")==0?BANK_DECISION_REJECTED:BANK_DECISION_PROPOSED;}
static BankDecisionRecord *read_decision(DatabaseStatement*s){char*v[7]={0};int64_t flags[4]={0};gboolean ok=TRUE;for(int i=0;i<7;i++)ok&=database_statement_column_text(s,i,&v[i]);for(int i=0;i<4;i++)ok&=database_statement_column_int64(s,7+i,&flags[i]);BankDecisionRecord x={.id=v[0],.observation_id=v[1],.proposal_id=v[2],.revision_id=v[3],.decision=decision_from(v[4]),.created_at=v[6],.create_account=flags[0],.reuse_account=flags[1],.create_holder=flags[2],.create_transaction=flags[3]};BankDecisionRecord*r=ok?bank_decision_record_copy(&x):NULL;for(int i=0;i<7;i++)g_free(v[i]);return r;}
static GPtrArray *decision_query(BankReviewDao*d,const char*where,const char*id,GError**e){char*sql=g_strdup_printf("SELECT * FROM bank_decisions WHERE %s ORDER BY created_at,id;",where);DatabaseStatement*s=database_statement_prepare(d?d->d:NULL,sql);g_free(sql);GPtrArray*a=g_ptr_array_new_with_free_func((GDestroyNotify)bank_decision_record_free);if(!s||!bind(s,1,id))goto bad;for(;;){DatabaseStatementStepResult step=database_statement_step(s);if(step==DATABASE_STATEMENT_STEP_DONE)break;if(step!=DATABASE_STATEMENT_STEP_ROW)goto bad;BankDecisionRecord*r=read_decision(s);if(!r)goto bad;g_ptr_array_add(a,r);}database_statement_finalize(s);return a;bad:database_statement_finalize(s);g_ptr_array_unref(a);fail(e,"Lecture des décisions impossible.");return NULL;}
