BankDecisionRecord *bank_review_dao_find_decision(BankReviewDao*d,const char*id,GError**e){GPtrArray*a=decision_query(d,"id=?",id,e);if(!a)return NULL;BankDecisionRecord*r=a->len?bank_decision_record_copy(g_ptr_array_index(a,0)):NULL;g_ptr_array_unref(a);return r;}

static GPtrArray *proposal_strings(Database*d,const char*sql,const char*id){DatabaseStatement*s=database_statement_prepare(d,sql);GPtrArray*a=g_ptr_array_new_with_free_func(g_free);if(!s||!bind(s,1,id)){database_statement_finalize(s);g_ptr_array_unref(a);return NULL;}for(;;){DatabaseStatementStepResult step=database_statement_step(s);if(step==DATABASE_STATEMENT_STEP_DONE)break;if(step!=DATABASE_STATEMENT_STEP_ROW){database_statement_finalize(s);g_ptr_array_unref(a);return NULL;}char*v=NULL;if(!database_statement_column_text(s,0,&v)){database_statement_finalize(s);g_ptr_array_unref(a);return NULL;}g_ptr_array_add(a,v);}database_statement_finalize(s);return a;}
static BankProposalRecord *read_proposal(BankReviewDao*d,DatabaseStatement*s){char*v[5]={0};int64_t start=0,end=0,ambiguous=0;gboolean ok=database_statement_column_text(s,0,&v[0])&&database_statement_column_text(s,1,&v[1])&&database_statement_column_text(s,2,&v[2])&&database_statement_column_int64(s,3,&start)&&database_statement_column_int64(s,4,&end)&&database_statement_column_int64(s,5,&ambiguous)&&database_statement_column_text(s,6,&v[3])&&database_statement_column_text(s,7,&v[4]);GPtrArray*ids=ok?proposal_strings(d->d,"SELECT observation_id FROM bank_proposal_observations WHERE proposal_id=? ORDER BY position;",v[0]):NULL;GPtrArray*roles=ids?proposal_strings(d->d,"SELECT role FROM bank_proposal_observations WHERE proposal_id=? ORDER BY position;",v[0]):NULL;GPtrArray*reasons=roles?proposal_strings(d->d,"SELECT reason FROM bank_proposal_reasons WHERE proposal_id=? ORDER BY position;",v[0]):NULL;BankProposalRecord x={.id=v[0],.investigation_id=v[1],.evidence_id=v[2],.start_offset=(gsize)start,.end_offset=(gsize)end,.ambiguous=ambiguous,.origin=origin_from(v[3]),.created_at=v[4],.observation_ids=ids,.roles=roles,.reasons=reasons};BankProposalRecord*r=reasons?bank_proposal_record_copy(&x):NULL;g_clear_pointer(&ids,g_ptr_array_unref);g_clear_pointer(&roles,g_ptr_array_unref);g_clear_pointer(&reasons,g_ptr_array_unref);for(guint i=0;i<5;i++)g_free(v[i]);return r;}
static GPtrArray *proposal_query(BankReviewDao*d,const char*where,const char*id,GError**e){char*sql=g_strdup_printf("SELECT * FROM bank_proposals WHERE %s ORDER BY created_at,id;",where);DatabaseStatement*s=database_statement_prepare(d?d->d:NULL,sql);g_free(sql);GPtrArray*a=g_ptr_array_new_with_free_func((GDestroyNotify)bank_proposal_record_free);if(!s||!bind(s,1,id))goto bad;for(;;){DatabaseStatementStepResult step=database_statement_step(s);if(step==DATABASE_STATEMENT_STEP_DONE)break;if(step!=DATABASE_STATEMENT_STEP_ROW)goto bad;BankProposalRecord*r=read_proposal(d,s);if(!r)goto bad;g_ptr_array_add(a,r);}database_statement_finalize(s);return a;bad:database_statement_finalize(s);g_ptr_array_unref(a);fail(e,"Lecture des propositions impossible.");return NULL;}
