static const char *state_code(BankAccountState s){return s==BANK_ACCOUNT_STATE_ACTIVE?"active":s==BANK_ACCOUNT_STATE_CLOSED?"closed":"unknown";}
gboolean bank_account_dao_insert(BankAccountDao*d,const BankAccountRecord*r,GError**e){BankAccountRecord*v=bank_account_record_copy(r);char*canonical=v?iban_analyzer_normalize_canonical(v->iban_normalized):NULL;if(!d||!v||!canonical||!iban_analyzer_validate_canonical(canonical)||g_strcmp0(canonical,v->iban_normalized)!=0||strncmp(v->country_code,canonical,2)!=0||(v->bic&&bic_validator_check(v->bic)!=BIC_VALIDATOR_VALID)){g_free(canonical);bank_account_record_free(v);fail(e,"Compte bancaire confirmé invalide ou non pris en charge.");return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO bank_accounts VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?);");gboolean ok=s&&bind(s,1,v->entity_id)&&bind(s,2,v->investigation_id)&&bind(s,3,canonical)&&bind(s,4,v->country_code)&&bind(s,5,v->bank_code)&&bind(s,6,v->branch_code)&&bind(s,7,v->account_number)&&bind(s,8,v->rib_key)&&bind(s,9,v->bic)&&bind(s,10,v->declared_institution)&&bind(s,11,state_code(v->state))&&bind(s,12,v->first_observed_at)&&bind(s,13,v->last_observed_at)&&bind(s,14,v->factual_notes)&&done(s);database_statement_finalize(s);g_free(canonical);bank_account_record_free(v);if(!ok)fail(e,"Insertion du compte bancaire impossible.");return ok;}
static BankAccountRecord *read_account(DatabaseStatement*s){char*v[14]={0};gboolean ok=TRUE;for(int i=0;i<14;i++)ok&=database_statement_column_text(s,i,&v[i]);BankAccountRecord x={.entity_id=v[0],.investigation_id=v[1],.iban_normalized=v[2],.country_code=v[3],.bank_code=v[4],.branch_code=v[5],.account_number=v[6],.rib_key=v[7],.bic=v[8],.declared_institution=v[9],.state=g_strcmp0(v[10],"active")==0?BANK_ACCOUNT_STATE_ACTIVE:g_strcmp0(v[10],"closed")==0?BANK_ACCOUNT_STATE_CLOSED:BANK_ACCOUNT_STATE_UNKNOWN,.first_observed_at=v[11],.last_observed_at=v[12],.factual_notes=v[13]};BankAccountRecord*r=ok?bank_account_record_copy(&x):NULL;for(int i=0;i<14;i++)g_free(v[i]);return r;}
static GPtrArray *account_query(BankAccountDao*d,const char*where,const char*id,GError**e){char*sql=g_strdup_printf("SELECT * FROM bank_accounts WHERE %s ORDER BY entity_id;",where);DatabaseStatement*s=database_statement_prepare(d?d->d:NULL,sql);g_free(sql);GPtrArray*a=g_ptr_array_new_with_free_func((GDestroyNotify)bank_account_record_free);if(!s||!bind(s,1,id))goto bad;for(;;){DatabaseStatementStepResult st=database_statement_step(s);if(st==DATABASE_STATEMENT_STEP_DONE)break;if(st!=DATABASE_STATEMENT_STEP_ROW)goto bad;BankAccountRecord*r=read_account(s);if(!r)goto bad;g_ptr_array_add(a,r);}database_statement_finalize(s);return a;bad:database_statement_finalize(s);g_ptr_array_unref(a);fail(e,"Lecture des comptes impossible.");return NULL;}
