gboolean financial_transaction_dao_insert(FinancialTransactionDao*d,const FinancialTransactionRecord*r,GError**e){FinancialTransactionRecord*v=financial_transaction_record_copy(r);if(!d||!v){fail(e,"Transaction observée invalide.");return FALSE;}DatabaseStatement*s=database_statement_prepare(d->d,"INSERT INTO financial_transactions VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);");const char*vals[]={v->id,v->investigation_id,v->transaction_type,v->observed_date_raw,v->observed_time_raw,v->observed_at_normalized,v->amount_decimal,v->currency,v->observed_status,v->bank_reference,v->reference_type,v->uetr,v->debtor_account_id,v->creditor_account_id,v->declared_payer,v->declared_beneficiary,v->source_institution,v->evidence_id,v->source_observation_id,v->source_proposal_id,v->decision_id,"human",v->factual_notes,v->created_at};gboolean ok=s!=NULL;for(guint i=0;ok&&i<G_N_ELEMENTS(vals);i++)ok=bind(s,i+1,vals[i]);ok=ok&&done(s);database_statement_finalize(s);financial_transaction_record_free(v);if(!ok)fail(e,"Insertion de la transaction observée impossible.");return ok;}
static FinancialTransactionRecord *read_transaction(DatabaseStatement*s){char*v[24]={0};gboolean ok=TRUE;for(int i=0;i<24;i++)ok&=database_statement_column_text(s,i,&v[i]);FinancialTransactionRecord x={.id=v[0],.investigation_id=v[1],.transaction_type=v[2],.observed_date_raw=v[3],.observed_time_raw=v[4],.observed_at_normalized=v[5],.amount_decimal=v[6],.currency=v[7],.observed_status=v[8],.bank_reference=v[9],.reference_type=v[10],.uetr=v[11],.debtor_account_id=v[12],.creditor_account_id=v[13],.declared_payer=v[14],.declared_beneficiary=v[15],.source_institution=v[16],.evidence_id=v[17],.source_observation_id=v[18],.source_proposal_id=v[19],.decision_id=v[20],.factual_notes=v[22],.created_at=v[23]};FinancialTransactionRecord*r=ok?financial_transaction_record_copy(&x):NULL;for(int i=0;i<24;i++)g_free(v[i]);return r;}
static GPtrArray *transaction_query(FinancialTransactionDao*d,const char*where,const char*id,GError**e){char*sql=g_strdup_printf("SELECT * FROM financial_transactions WHERE %s ORDER BY created_at,id;",where);DatabaseStatement*s=database_statement_prepare(d?d->d:NULL,sql);g_free(sql);GPtrArray*a=g_ptr_array_new_with_free_func((GDestroyNotify)financial_transaction_record_free);if(!s||!bind(s,1,id))goto bad;for(;;){DatabaseStatementStepResult st=database_statement_step(s);if(st==DATABASE_STATEMENT_STEP_DONE)break;if(st!=DATABASE_STATEMENT_STEP_ROW)goto bad;FinancialTransactionRecord*r=read_transaction(s);if(!r)goto bad;g_ptr_array_add(a,r);}database_statement_finalize(s);return a;bad:database_statement_finalize(s);g_ptr_array_unref(a);fail(e,"Lecture des transactions impossible.");return NULL;}
